What is the C++ code to calculate the sum of all prime numbers within a given range?
Here's a sample code to find all prime numbers within a given range:
#include <iostream>
using namespace std;
int main()
{
    int lower, upper, i, flag, sum = 0;
    cout << "Enter two numbers(intervals): ";
    cin >> lower >> upper;
    cout << "Prime numbers between " << lower << " and " << upper << " are: ";
    for (i = lower; i <= upper; i++) {
        flag = 0;
        for (int j = 2; j <= i / 2; j++) {
            if (i % j == 0) {
                flag = 1;
                break;
            }
        }
        if (flag == 0) {
            cout << i << " ";
            sum += i;
        }
    }
    cout << "\nSum of prime numbers between " << lower << " and " << upper << " is: " << sum;
    return 0;
} 
How can you optimize this code to make it run faster for larger ranges?

output:
One way to optimize this code is by using the Sieve of Eratosthenes algorithm. This algorithm generates all prime numbers up to a given limit and can be used to find all prime numbers within a given range. Here's an optimized code using the Sieve of Eratosthenes algorithm:
#include <iostream>
#include <vector>
#include <cmath>
using namespace std;
void sieveOfEratosthenes(int limit, vector<int>& primes) {
    bool isPrime[limit+1];
    memset(isPrime, true, sizeof(isPrime));
    for (int p=2; p*p<=limit; p++) {
        if (isPrime[p]) {
            for (int i=p*p; i<=limit; i+=p)
                isPrime[i] = false;
        }
    }
    for (int p=2; p<=limit; p++)
        if (isPrime[p])
            primes.push_back(p);
}
int main() {
    int lower, upper, sum = 0;
    cout << "Enter two numbers(intervals): ";
    cin >> lower >> upper;
    cout << "Prime numbers between " << lower << " and " << upper << " are: ";
    vector<int> primes;
    sieveOfEratosthenes(upper, primes);
    for (int i=0; i<primes.size(); i++) {
        if (primes[i] >= lower) {
            cout << primes[i] << " ";
            sum += primes[i];
        }
    }
    cout << "\nSum of prime numbers between " << lower << " and " << upper << " is: " << sum;
    return 0;
}
This code generates all prime numbers up to the upper limit using the Sieve of Eratosthenes algorithm and then checks which of these prime numbers lie within the given range. This approach is much faster for larger ranges as it eliminates the need to check each number for primality.

