```
using System;
using System.Data;
using System.Linq;
namespace PrecipitationAnalysis
{
    class Program
    {
        static void Main(string[] args)
        {
            // Input parameters
            int minElevation = 0;
            int maxElevation = 1000;
            string location = "South Africa";
            // Sample data table
            DataTable data = new DataTable();
            data.Columns.Add("PrecipitationType", typeof(string));
            data.Columns.Add("Elevation", typeof(int));
            data.Columns.Add("Location", typeof(string));
            data.Rows.Add("Rain", 500, "South Africa");
