import javax.imageio.ImageIO;
public class ImageRecognition {
  public static void main(String[] args) throws Exception {
    byte[] imageBytes = getImageBytes("nature_painting.jpg");
    List<String> labels = getLabels("labels.txt");
    try (Tensor<Float> normalizedImage = normalizeImage(imageBytes)) {
      float[] labelProbabilities = executeInceptionGraph(normalizedImage);
      int bestLabelIdx = maxIndex(labelProbabilities);
      String bestLabel = labels.get(bestLabelIdx);
      System.out.println("Nature painting contains " + bestLabel);
    }
  }
  private static byte[] getImageBytes(String filename) throws IOException {
    BufferedImage image = ImageIO.read(new File(filename));
    ByteArrayOutputStream byteArrayOutputStream = new ByteArrayOutputStream();
    ImageIO.write(image, "jpg", byteArrayOutputStream);
    return byteArrayOutputStream.toByteArray();
  }
  private static List<String> getLabels(String filename) throws IOException {
    Path labelFile = Paths.get(filename);
    return Files.readAllLines(labelFile, Charset.forName("UTF-8"));
  }
  private static Tensor<Float> normalizeImage(byte[] imageBytes) {
    try (Graph g = new Graph()) {
      GraphBuilder b = new GraphBuilder(g);
      final int H = 299;
      final int W = 299;
      final float mean = 0;
      final float scale = 255;
      final int channels = 3;
      final int[] shape = new int[] {1, H, W, channels};
      final String inputName = "input";
      final String outputName = "output";
      b.op("Cast", inputName, b.constant(imageBytes));
      b.op("ExpandDims", inputName, b.constant(0));
      b.op("ResizeBilinear", inputName, b.squeeze(b.cast(inputName, DataType.FLOAT)), b.constant(new int[] {H, W}));
      b.op("Sub", inputName, b.div(b.cast(inputName, DataType.FLOAT), b.constant(scale)), b.constant(mean));
      b.op("Mul", outputName, b.cast(b.constant(1.0), DataType.FLOAT), inputName);
      Session s = new Session(g);
      Tensor<Float> result = s.runner().fetch(outputName).run().get(0).expect(Float.class);
      return result;
    }
  }
  private static float[] executeInceptionGraph(Tensor<Float> image) {
    try (Graph g = new Graph()) {
      GraphBuilder b = new GraphBuilder(g);
      final String inputName = "input";
      final String outputName = "output";
      final long[] shape = image.shape();
      final int numLabels = 1001;
      byte[] graphDef = readAllBytesOrExit(Paths.get("tensorflow_inception_graph.pb"));
      b.importGraphDef(graphDef);
      Session s = new Session(g);
      Tensor<Float> result = s.runner().feed(inputName, image).fetch(outputName).run().get(0).expect(Float.class);
      float[] labelProbabilities = result.copyTo(new float[1][numLabels])[0];
      result.close();
      return labelProbabilities;
    }
  }
  private static int maxIndex(float[] probabilities) {
    int best = 0;
    for (int i = 1; i < probabilities.length; ++i) {
      if (probabilities[i] > probabilities[best]) {
        best = i;
      }
    }
    return best;
  }
  private static class GraphBuilder {
