% Load the required NLP resources
nlp = nlp();
% Define the sentence to process
sentence = "The cat jumped over the fence";
% Tokenize the sentence
tokens = tokenize(nlp, sentence);
% Identify the parts of speech for each token
pos = partsOfSpeech(nlp, tokens);
% Remove all nouns from the sentence
nouns = ismember(pos, {'NN', 'NNS', 'NNP', 'NNPS'});
