    int atomic_numbers[10] = {1, 2, 3, 4, 6, 7, 8, 9, 10, 11};
    string symbols[10] = {"H", "He", "Li", "Be", "C", "N", "O", "F", "Ne", "Na"};
    string electron_configs[10] = {"1s1", "1s2", "[He] 2s1", "[He] 2s2", "[He] 2s2 2p2", "[He] 2s2 2p3", "[He] 2s2 2p4", "[He] 2s2 2p5", "[He] 2s2 2p6", "[Ne] 3s1"};

    // Generate 5 random questions
    for (int i = 0; i < 5; i++)
    {
        // Choose a random element
        int index = rand() % 10;
        string element = elements[index];

        // Choose a random property to ask about
        int property = rand() % 3;
        string question, answer;
        switch (property)
        {
            case 0:
                // Ask about the atomic number
                question = "What is the atomic number of " + element + "?";
                answer = to_string(atomic_numbers[index]);
                break;
            case 1:
                // Ask about the symbol
                question = "What is the symbol for " + element + "?";
                answer = symbols[index];
                break;
            case 2:
                // Ask about the electron configuration
                question = "What is the electron configuration of " + element + "?";
                answer = electron_configs[index];
                break;
        }

        // Generate 3 random wrong answers
        string wrong_answers[3];
        for (int j = 0; j < 3; j++)
        {
            int wrong_index = rand() % 10;
            while (wrong_index == index)
            {
                wrong_index = rand() % 10;
            }
            switch (property)
            {
                case 0:
                    wrong_answers[j] = to_string(atomic_numbers[wrong_index]);
                    break;
                case 1:
                    wrong_answers[j] = symbols[wrong_index];
                    break;
                case 2:
                    wrong_answers[j] = electron_configs[wrong_index];
                    break;
            }
        }

        // Shuffle the answers
        string all_answers[4] = {answer, wrong_answers[0], wrong_answers[1], wrong_answers[2]};
        for (int j = 0; j < 4; j++)
        {
            int swap_index = rand() % 4;
            string temp = all_answers[j];
            all_answers[j] = all_answers[swap_index];
            all_answers[swap_index] = temp;
        }

        // Print the question and answers
        cout << "Question " << i+1 << ": " << question << endl;
        for (int j = 0; j < 4; j++)
        {
            cout << j+1 << ") " << all_answers[j] << endl;
        }
        cout << "Answer: " << answer << endl << endl;
    }

    return 0;
}
```
This program generates 5 random multiple choice questions about the periodic table, with each question having 4 possible answers and only one correct answer. The questions are based on the properties of randomly selected elements, including their atomic number, symbol, and electron configuration. The program shuffles the answers to make the questions more challenging. The output includes the correct answer to each question.

