```
#include <iostream>
#include <sstream>
#include <string>
#include <vector>
std::vector<std::string> tokenize(const std::string& str)
{
    std::vector<std::string> tokens;
    std::stringstream ss(str);
    std::string token;
    while (ss >> token)
    {
        tokens.push_back(token);
    }
    return tokens;
}
```
Step 2: Identify the presence of a group of astronauts being sent on a mission to explore a newly discovered planet
We can search for keywords and phrases that indicate the presence of a group of astronauts being sent on a mission to explore a newly discovered planet. Some examples of such keywords and phrases are "astronauts," "mission," "explore," and "newly discovered planet." We can use the `std::find` function from the C++ standard library to search for these keywords and phrases.
```
bool hasAstronauts(const std::vector<std::string>& tokens)
{
    const std::vector<std::string> keywords = {"astronauts", "mission", "explore", "newly", "discovered", "planet"};
    for (const auto& keyword : keywords)
    {
        if (std::find(tokens.begin(), tokens.end(), keyword) != tokens.end())
        {
            return true;
        }
    }
    return false;
}
