Here's some sample Java code to decode a message using the steps you outlined:
```java
public class MessageDecoder {
    public static void main(String[] args) {
        String message = "This is a secret message that needs to be decoded";
        String[] words = message.split(" ");
        StringBuilder decodedMessage = new StringBuilder();
        for (int i = 0; i < words.length; i++) {
            String word = words[i];
            if (i % 2 == 0) {
                // Reverse the order of the letters in even numbered words
                word = reverseWord(word);
            } else {
                // Shift each letter in odd numbered words three letters to the right
                word = shiftWord(word, 3);
            }
            // Replace vowels with the next letter in the alphabet
            word = replaceVowels(word);
            decodedMessage.append(word).append(" ");
        }
        System.out.println("Decoded message: " + decodedMessage.toString());
        // Use the instructions within the decoded message to complete a task
        // ...
    }
    private static String reverseWord(String word) {
        StringBuilder reversedWord = new StringBuilder();
        for (int i = word.length() - 1; i >= 0; i--) {
            reversedWord.append(word.charAt(i));
        }
        return reversedWord.toString();
    }
    private static String shiftWord(String word, int shift) {
        StringBuilder shiftedWord = new StringBuilder();
        for (int i = 0; i < word.length(); i++) {
            char c = word.charAt(i);
            if (Character.isLetter(c)) {
                char shiftedChar = (char) (c + shift);
                if (shiftedChar > 'z') {
                    shiftedChar = (char) (shiftedChar - 26);
                }
                shiftedWord.append(shiftedChar);
            } else {
                shiftedWord.append(c);
            }
        }
        return shiftedWord.toString();
    }
    private static String replaceVowels(String word) {
        StringBuilder replacedWord = new StringBuilder();
        for (int i = 0; i < word.length(); i++) {
            char c = word.charAt(i);
            if (isVowel(c)) {
                char replacedChar = (char) (c + 1);
                if (replacedChar == 'a' || replacedChar == 'e' || replacedChar == 'i' || replacedChar == 'o' || replacedChar == 'u') {
                    replacedChar = (char) (replacedChar + 1);
                }
                replacedWord.append(replacedChar);
            } else {
                replacedWord.append(c);
            }
        }
        return replacedWord.toString();
    }
    private static boolean isVowel(char c) {
        return c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u';
    }
}
```
