```java
import org.bouncycastle.crypto.BlockCipher;
import org.bouncycastle.crypto.engines.AESEngine;
import org.bouncycastle.crypto.modes.GCMBlockCipher;
import org.bouncycastle.crypto.params.AEADParameters;
import org.bouncycastle.crypto.params.KeyParameter;
public class EncryptionExample {
    public static void main(String[] args) {
        byte[] key = "mySecretKey".getBytes();
        byte[] data = "mySensitiveData".getBytes();
        BlockCipher engine = new AESEngine();
        GCMBlockCipher cipher = new GCMBlockCipher(engine);
        KeyParameter keyParam = new KeyParameter(key);
        AEADParameters params = new AEADParameters(keyParam, 128, null, null);
        cipher.init(true, params);
        byte[] encrypted = new byte[cipher.getOutputSize(data.length)];
        int len = cipher.processBytes(data, 0, data.length, encrypted, 0);
        try {
            cipher.doFinal(encrypted, len);
        } catch (Exception e) {
            e.printStackTrace();
        }
        System.out.println("Encrypted data: " + new String(encrypted));
    }
}
```
